    "subtopicId": "basis-indep",
    "questionNumber": 45,
    "title": "Linear Independence via Determinant #45",
    "difficulty": "Advanced",
    "skill": "Conceptual",
    "problem": "Do the vectors $v_1 = (1, 0, 0)$, $v_2 = (1, 1, 0)$, and $v_3 = (2, 3, 2)$ form a basis for $\\mathbb{R}^3$?",
    "hint": "Put the vectors into a 3x3 matrix and check if the determinant is non-zero.",
